<?php
require_once '../includes/farmacia.php';exigirPermiso('compras.ver');$db=farmaciaDb();$stmt=$db->prepare('SELECT c.*,p.Nombre,u.NombreCompleto,ua.NombreCompleto AS AnuladoPor FROM Compras c JOIN Proveedores p ON p.ProveedorID=c.ProveedorID JOIN Usuarios u ON u.UsuarioID=c.UsuarioID LEFT JOIN Usuarios ua ON ua.UsuarioID=c.UsuarioAnulacion WHERE CompraID=?');$stmt->execute([(int)($_GET['id']??0)]);$c=$stmt->fetch(PDO::FETCH_ASSOC);if(!$c){http_response_code(404);exit('Compra no encontrada.');}
$stmt=$db->prepare('SELECT d.*,m.NombreMedicamento,m.UnidadBase,l.NumeroLote,l.FechaVencimiento FROM CompraDetalle d JOIN Medicamentos m ON m.MedicamentoID=d.MedicamentoID JOIN LotesMedicamentos l ON l.LoteID=d.LoteID WHERE d.CompraID=? ORDER BY d.CompraDetalleID');$stmt->execute([$c['CompraID']]);$lineas=$stmt->fetchAll(PDO::FETCH_ASSOC);$verCostos=tienePermiso('medicamentos.costos');
$stmt=$db->prepare('SELECT CompraID,Estado,FechaRegistro,CompraOrigenID FROM Compras WHERE ProveedorID=? AND NumeroDocumento=? ORDER BY CompraID');$stmt->execute([$c['ProveedorID'],$c['NumeroDocumento']]);$versiones=$stmt->fetchAll(PDO::FETCH_ASSOC);
$hayVigente=false;foreach($versiones as $version)if($version['Estado']==='Recibida')$hayVigente=true;
$titulo='Compra #'.$c['CompraID'];require '../includes/header.php';
?>
<h1 class="page-title"><i class="bi bi-bag-check"></i> Compra #<?=$c['CompraID']?></h1>
<?php if(isset($_GET['guardado']) && $c['Estado']!=='Anulada'): ?><div class="alert alert-success">Recepción confirmada. Las unidades ya ingresaron al inventario.</div><?php endif; ?>

<?php if ($c['Estado'] === 'Anulada'): ?>
<div class="alert alert-danger"><h2 class="h6">Compra anulada</h2><p class="mb-1"><strong>Motivo:</strong> <?=h($c['MotivoAnulacion'])?></p><p class="mb-0"><strong>Responsable:</strong> <?=h($c['AnuladoPor'])?> · <?=h($c['FechaAnulacion'])?></p></div>
<?php endif; ?>
<div class="card"><div class="card-header">Datos de la recepción</div><div class="card-body row"><div class="col-md-6"><p><strong>Proveedor:</strong> <?=h($c['Nombre'])?></p><p><strong>Documento:</strong> <?=h($c['NumeroDocumento'])?></p><p><strong>Estado:</strong> <span class="badge <?=$c['Estado']==='Anulada'?'bg-danger':'bg-success'?>"><?=h($c['Estado'])?></span></p><p><strong>Fecha de recepción:</strong> <?=h($c['FechaCompra'])?></p></div><div class="col-md-6"><p><strong>Registrado por:</strong> <?=h($c['NombreCompleto'])?></p><p><strong>Fecha de registro:</strong> <?=h($c['FechaRegistro'])?></p><p><strong>Observaciones:</strong> <?=h($c['Observaciones'])?></p></div></div></div>
<div class="card"><div class="card-header">Productos ingresados</div><div class="card-body table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Presentación</th><th>Cantidad</th><th>Equivalencia</th><th>Unidades ingresadas</th><th>Lote</th><th>Vencimiento</th><?php if($verCostos): ?><th>Costo/presentación</th><th>Subtotal</th><?php endif; ?></tr></thead><tbody><?php foreach($lineas as $d): ?><tr><td><?=h($d['NombreMedicamento'])?></td><td><?=h($d['PresentacionNombre'])?></td><td><?=h($d['Cantidad'])?></td><td><?=h($d['UnidadesPorPresentacion'])?> <?=h($d['UnidadBase'])?></td><td><?=h($d['UnidadesRecibidas'])?></td><td><?=h($d['NumeroLote'])?></td><td><?=h($d['FechaVencimiento'])?></td><?php if($verCostos): ?><td><?=dinero($d['CostoPresentacion'])?></td><td><?=dinero($d['Subtotal'])?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table><?php if($verCostos): ?><p class="text-end fs-5"><strong>Total: <?=dinero($c['Total'])?></strong></p><?php endif; ?></div></div><a class="btn btn-secondary" href="index.php">Volver a compras</a>
<?php if($c['Estado']==='Recibida' && tienePermiso('compras.anular')): ?> <a class="btn btn-outline-danger" href="anular.php?id=<?=$c['CompraID']?>">Anular compra</a><?php endif; ?>

<?php if($c['Estado']==='Anulada' && !$hayVigente && tienePermiso('compras.corregir') && tienePermiso('compras.crear')): ?> <a class="btn btn-primary" href="nueva.php?origen=<?=$c['CompraID']?>">Corregir compra</a><?php endif; ?>
<?php if(count($versiones)>1 || $c['CompraOrigenID']): ?><div class="card mt-3"><div class="card-header">Historial de la referencia <?=h($c['NumeroDocumento'])?></div><div class="card-body table-responsive"><table class="table table-sm"><thead><tr><th>Compra</th><th>Estado</th><th>Fecha</th><th>Corrige a</th></tr></thead><tbody><?php foreach($versiones as $version): ?><tr><td><a href="ver.php?id=<?=$version['CompraID']?>">#<?=$version['CompraID']?></a></td><td><?=h($version['Estado'])?></td><td><?=h($version['FechaRegistro'])?></td><td><?=h($version['CompraOrigenID']?'#'.$version['CompraOrigenID']:'Original')?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
<?php require '../includes/footer.php'; ?>

